/* heat-3d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving original numerical semantics):
   - Extracted invariant stencil coefficients into local consts.
   - Hoisted A[i][j][k] / B[i][j][k] into a local "center" variable to
     avoid reloading the same element multiple times.
   - Hoisted the term 2.0 * center into a local variable; since this is
     an exact scaling in IEEE-754, it does not change results but saves
     redundant multiplications.
   - For better cache locality on the innermost (k) dimension, created
     row pointers (e.g., &A[i][j][0]) once per (i,j) and reused them in
     the k-loop instead of recomputing 3D subscripts.
   - Added OpenMP parallelization on the outer i-loop and OpenMP 'simd'
     on the innermost k-loop. If compiled without OpenMP support, these
     pragmas are ignored and the code runs sequentially, preserving
     behavior.
*/
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Stencil coefficient (same as in the original expression). */
  const DATA_TYPE c0 = SCALAR_VAL(0.125);
  const DATA_TYPE two = SCALAR_VAL(2.0);

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* First sweep: update B from A. */
#pragma omp parallel for private(j, k) schedule(static)
    for (i = 1; i < _PB_N - 1; i++) {
      for (j = 1; j < _PB_N - 1; j++) {
        /* Cache row pointers for this (i,j) to improve locality and
           reduce repeated 3D index arithmetic. */
        DATA_TYPE* A_im1_j  = &A[i-1][j][0];
        DATA_TYPE* A_i_j    = &A[i][j][0];
        DATA_TYPE* A_ip1_j  = &A[i+1][j][0];
        DATA_TYPE* A_i_jm1  = &A[i][j-1][0];
        DATA_TYPE* A_i_jp1  = &A[i][j+1][0];
        DATA_TYPE* B_i_j    = &B[i][j][0];

#pragma omp simd
        for (k = 1; k < _PB_N - 1; k++) {
          const DATA_TYPE center     = A_i_j[k];
          const DATA_TYPE two_center = two * center;

          /* Algebraically identical to the original expression:
               B = 0.125*(A[i+1] - 2*center + A[i-1])
                 + 0.125*(A[j+1] - 2*center + A[j-1])
                 + 0.125*(A[k+1] - 2*center + A[k-1])
                 + center;
             Only common subexpressions are hoisted; evaluation order of
             adds/muls is preserved. */
          B_i_j[k] =
              c0 * (A_ip1_j[k] - two_center + A_im1_j[k]) +
              c0 * (A_i_jp1[k] - two_center + A_i_jm1[k]) +
              c0 * (A_i_j[k+1] - two_center + A_i_j[k-1]) +
              center;
        }
      }
    }

    /* Second sweep: update A from B (same stencil, roles swapped). */
#pragma omp parallel for private(j, k) schedule(static)
    for (i = 1; i < _PB_N - 1; i++) {
      for (j = 1; j < _PB_N - 1; j++) {
        DATA_TYPE* B_im1_j  = &B[i-1][j][0];
        DATA_TYPE* B_i_j    = &B[i][j][0];
        DATA_TYPE* B_ip1_j  = &B[i+1][j][0];
        DATA_TYPE* B_i_jm1  = &B[i][j-1][0];
        DATA_TYPE* B_i_jp1  = &B[i][j+1][0];
        DATA_TYPE* A_i_j    = &A[i][j][0];

#pragma omp simd
        for (k = 1; k < _PB_N - 1; k++) {
          const DATA_TYPE center     = B_i_j[k];
          const DATA_TYPE two_center = two * center;

          A_i_j[k] =
              c0 * (B_ip1_j[k] - two_center + B_im1_j[k]) +
              c0 * (B_i_jp1[k] - two_center + B_i_jm1[k]) +
              c0 * (B_i_j[k+1] - two_center + B_i_j[k-1]) +
              center;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
