}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* The effective problem size used in PolyBench loops. */
  const int n_inner = _PB_N;

  /* Frequently used scalar constants. Hoisted once out of the loops
     so that the compiler does not need to recompute SCALAR_VAL(...)
     for every lattice point. */
  const DATA_TYPE c0  = SCALAR_VAL(0.125);
  const DATA_TYPE c2  = SCALAR_VAL(2.0);

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* First sweep: update B from A.
       - Parallelized over i and j.
       - k remains innermost to keep accesses to A[i][j][k] contiguous.
       - Within each (i,j) tile we create 1D pointers along k to improve
         address generation and help vectorization.
       - We also compute -2*A[i][j][k] once and reuse it in the three
         1D second-order differences, avoiding two redundant multiplies. */
#pragma omp parallel for collapse(2) private(k) schedule(static)
    for (i = 1; i < n_inner-1; i++) {
      for (j = 1; j < n_inner-1; j++) {

        /* Pointers to contiguous lines in the k-dimension. These are
           all non-overlapping views into A/B for this particular (i,j)
           pair, so it is safe to qualify them with restrict. */
        DATA_TYPE * restrict a_center = &A[i  ][j  ][0];
        DATA_TYPE * restrict a_im1    = &A[i-1][j  ][0];
        DATA_TYPE * restrict a_ip1    = &A[i+1][j  ][0];
        DATA_TYPE * restrict a_jm1    = &A[i  ][j-1][0];
        DATA_TYPE * restrict a_jp1    = &A[i  ][j+1][0];
        DATA_TYPE * restrict b_center = &B[i  ][j  ][0];

        for (k = 1; k < n_inner-1; k++) {
          const DATA_TYPE center          = a_center[k];
          const DATA_TYPE neg_two_center  = -c2 * center;

          /* 1D second derivatives in x, y, z directions.  The algebra
             is identical to the original expression:
               A[i+1] - 2*A[i] + A[i-1]
             but we reuse (-2*A[i]) across the three directions. */
          const DATA_TYPE tmp_x = a_ip1[k]      + neg_two_center + a_im1[k];
          const DATA_TYPE tmp_y = a_jp1[k]      + neg_two_center + a_jm1[k];
          const DATA_TYPE tmp_z = a_center[k+1] + neg_two_center + a_center[k-1];

          b_center[k] = c0 * tmp_x
                      + c0 * tmp_y
                      + c0 * tmp_z
                      + center;
        }
      }
    }

    /* Second sweep: update A from B.
       This is structurally identical to the first sweep with A and B
       exchanged. */
#pragma omp parallel for collapse(2) private(k) schedule(static)
    for (i = 1; i < n_inner-1; i++) {
      for (j = 1; j < n_inner-1; j++) {

        DATA_TYPE * restrict b_center = &B[i  ][j  ][0];
        DATA_TYPE * restrict b_im1    = &B[i-1][j  ][0];
        DATA_TYPE * restrict b_ip1    = &B[i+1][j  ][0];
        DATA_TYPE * restrict b_jm1    = &B[i  ][j-1][0];
        DATA_TYPE * restrict b_jp1    = &B[i  ][j+1][0];
        DATA_TYPE * restrict a_center = &A[i  ][j  ][0];

        for (k = 1; k < n_inner-1; k++) {
          const DATA_TYPE center          = b_center[k];
          const DATA_TYPE neg_two_center  = -c2 * center;

          const DATA_TYPE tmp_x = b_ip1[k]      + neg_two_center + b_im1[k];
          const DATA_TYPE tmp_y = b_jp1[k]      + neg_two_center + b_jm1[k];
          const DATA_TYPE tmp_z = b_center[k+1] + neg_two_center + b_center[k-1];

          a_center[k] = c0 * tmp_x
                      + c0 * tmp_y
                      + c0 * tmp_z
                      + center;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
