   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d [[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* tsteps is kept only to preserve the original interface.
     The reference PolyBench implementation uses the compile-time
     constant TSTEPS for the loop bound, so we do the same here. */
  (void)tsteps;

  /* Local aliases with 'restrict' to help the compiler reason about
     aliasing between A and B. */
  DATA_TYPE (* restrict A_)[n][n] = A;
  DATA_TYPE (* restrict B_)[n][n] = B;

  /* Use PolyBench's processed problem size for the loop bounds. */
  const int n_inner = _PB_N;

  /* Interior region (we do not update the outermost boundary). */
  const int i_start = 1;
  const int i_end   = n_inner - 1;
  const int j_start = 1;
  const int j_end   = n_inner - 1;
  const int k_start = 1;
  const int k_end   = n_inner - 1;

  /* Stencil coefficients, hoisted out of the loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.125);
  const DATA_TYPE c2 = SCALAR_VAL(2.0);

#pragma scop
  /* Parallelize over space for each time step.
     A single parallel region avoids repeated thread creation. */
  #pragma omp parallel
  {
    for (int t = 1; t <= TSTEPS; t++)
    {
      /* ------------------------------------------------------------------
       * First sweep: compute B from A.
       * Spatial blocking in i and j improves cache reuse in the j/k planes.
       * ------------------------------------------------------------------ */
      #pragma omp for collapse(2) schedule(static)
      for (int ii = i_start; ii < i_end; ii += HEAT3D_BLOCK_I)
        for (int jj = j_start; jj < j_end; jj += HEAT3D_BLOCK_J)
        {
          const int i_max =
              (ii + HEAT3D_BLOCK_I < i_end) ? (ii + HEAT3D_BLOCK_I) : i_end;
          const int j_max =
              (jj + HEAT3D_BLOCK_J < j_end) ? (jj + HEAT3D_BLOCK_J) : j_end;

          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
            {
              /* 1D views for the current (i,j) row in each needed plane.
                 This turns the innermost loop into a simple, contiguous
                 1D stencil, improving cache usage and auto-vectorization. */
              DATA_TYPE * restrict Bij   = &B_[i][j][0];
              DATA_TYPE * restrict Aij   = &A_[i][j][0];
              DATA_TYPE * restrict Aip1j = &A_[i+1][j][0];
              DATA_TYPE * restrict Aim1j = &A_[i-1][j][0];
              DATA_TYPE * restrict Aijp1 = &A_[i][j+1][0];
              DATA_TYPE * restrict Aijm1 = &A_[i][j-1][0];

              #pragma omp simd
              for (int k = k_start; k < k_end; ++k)
              {
                const DATA_TYPE center   = Aij[k];
                const DATA_TYPE v2center = c2 * center;

                const DATA_TYPE t1 =
                    c0 * (Aip1j[k] - v2center + Aim1j[k]);
                const DATA_TYPE t2 =
                    c0 * (Aijp1[k] - v2center + Aijm1[k]);
                const DATA_TYPE t3 =
                    c0 * (Aij[k+1] - v2center + Aij[k-1]);

                Bij[k] = t1 + t2 + t3 + center;
              }
            }
        }

      /* ------------------------------------------------------------------
       * Second sweep: compute A from B.
       * The structure mirrors the first sweep.
       * ------------------------------------------------------------------ */
      #pragma omp for collapse(2) schedule(static)
      for (int ii = i_start; ii < i_end; ii += HEAT3D_BLOCK_I)
        for (int jj = j_start; jj < j_end; jj += HEAT3D_BLOCK_J)
        {
          const int i_max =
              (ii + HEAT3D_BLOCK_I < i_end) ? (ii + HEAT3D_BLOCK_I) : i_end;
          const int j_max =
              (jj + HEAT3D_BLOCK_J < j_end) ? (jj + HEAT3D_BLOCK_J) : j_end;

          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
            {
              DATA_TYPE * restrict Aij   = &A_[i][j][0];
              DATA_TYPE * restrict Bij   = &B_[i][j][0];
              DATA_TYPE * restrict Bip1j = &B_[i+1][j][0];
              DATA_TYPE * restrict Bim1j = &B_[i-1][j][0];
              DATA_TYPE * restrict Bijp1 = &B_[i][j+1][0];
              DATA_TYPE * restrict Bijm1 = &B_[i][j-1][0];

              #pragma omp simd
              for (int k = k_start; k < k_end; ++k)
              {
                const DATA_TYPE center   = Bij[k];
                const DATA_TYPE v2center = c2 * center;

                const DATA_TYPE t1 =
                    c0 * (Bip1j[k] - v2center + Bim1j[k]);
                const DATA_TYPE t2 =
                    c0 * (Bijp1[k] - v2center + Bijm1[k]);
                const DATA_TYPE t3 =
                    c0 * (Bij[k+1] - v2center + Bij[k-1]);

                Aij[k] = t1 + t2 + t3 + center;
              }
            }
        }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
