/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use the runtime sizes (tsteps, n) instead of compile-time macros.
   - Parallelize the spatial loops with OpenMP (if compiled with -fopenmp).
   - Vectorize the innermost k-loop via '#pragma omp simd'.
   - Improve data locality and reduce address computations by caching
     pointers to 1D rows (k-dimension) and the center value in registers.
   - Reuse precomputed stencil constants (0.125 and 2.0).
   The arithmetic expression itself is kept in the same form to preserve
   the original floating-point evaluation order as closely as possible.
*/
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* Interior region extents: indices [1, n-2] in each dimension. */
  const int i_start = 1;
  const int i_end   = n - 1; /* exclusive upper bound (last interior i == n-2) */
  const int j_start = 1;
  const int j_end   = n - 1;
  const int k_start = 1;
  const int k_end   = n - 1;

  /* Precompute constants used in the stencil. */
  const DATA_TYPE c0 = SCALAR_VAL(0.125);
  const DATA_TYPE c2 = SCALAR_VAL(2.0);

#pragma scop
#pragma omp parallel
  {
    /* Each thread iterates over all time steps; the work in each
       spatial sweep is distributed via 'omp for'. */
    for (int t = 1; t <= tsteps; t++)
    {
      /* First sweep: update B from A. */
#pragma omp for collapse(2) schedule(static)
      for (int i = i_start; i < i_end; i++)
      {
        for (int j = j_start; j < j_end; j++)
        {
          /* Cache the six neighbor rows and the target row.
             Each of these pointers refers to a distinct, non-overlapping
             1D row of length 'n' in memory, so 'restrict' is valid. */
          DATA_TYPE * restrict A_im1_j = A[i-1][j];
          DATA_TYPE * restrict A_i_j   = A[i  ][j];
          DATA_TYPE * restrict A_ip1_j = A[i+1][j];
          DATA_TYPE * restrict A_i_jm1 = A[i  ][j-1];
          DATA_TYPE * restrict A_i_jp1 = A[i  ][j+1];
          DATA_TYPE * restrict B_i_j   = B[i  ][j];

          /* k is the innermost (contiguous) dimension: good for SIMD.
             '#pragma omp simd' encourages explicit vectorization even
             when -fopenmp is not used, most compilers still treat this
             as a generic vectorization hint. */
#pragma omp simd
          for (int k = k_start; k < k_end; k++)
          {
            const DATA_TYPE center = A_i_j[k];

            B_i_j[k] =
              c0 * (A_ip1_j[k] - c2 * center + A_im1_j[k]) +
              c0 * (A_i_jp1[k] - c2 * center + A_i_jm1[k]) +
              c0 * (A_i_j[k+1] - c2 * center + A_i_j[k-1]) +
              center;
          }
        }
      }

      /* Implicit OpenMP barrier here: all of B has been computed. */

      /* Second sweep: update A from B. */
#pragma omp for collapse(2) schedule(static)
      for (int i = i_start; i < i_end; i++)
      {
        for (int j = j_start; j < j_end; j++)
        {
          DATA_TYPE * restrict B_im1_j = B[i-1][j];
          DATA_TYPE * restrict B_i_j   = B[i  ][j];
          DATA_TYPE * restrict B_ip1_j = B[i+1][j];
          DATA_TYPE * restrict B_i_jm1 = B[i  ][j-1];
          DATA_TYPE * restrict B_i_jp1 = B[i  ][j+1];
          DATA_TYPE * restrict A_i_j   = A[i  ][j];

#pragma omp simd
          for (int k = k_start; k < k_end; k++)
          {
            const DATA_TYPE center = B_i_j[k];

            A_i_j[k] =
              c0 * (B_ip1_j[k] - c2 * center + B_im1_j[k]) +
              c0 * (B_i_jp1[k] - c2 * center + B_i_jm1[k]) +
              c0 * (B_i_j[k+1] - c2 * center + B_i_j[k-1]) +
              center;
          }
        }
      }

      /* Another implicit OpenMP barrier at the end of the second
         'omp for' ensures that all of A is updated before the next
         time step starts. */
    }
  }
#pragma endscop

